      (HALO_TD_OUT - 1) * stride + dilation * (KD - 1) + 1;
  const int64_t haloTH64 =
      (HALO_TH_OUT - 1) * stride + dilation * (KH - 1) + 1;
  const int64_t haloTW64 =
      (HALO_TW_OUT - 1) * stride + dilation * (KW - 1) + 1;
  const int64_t haloTWP64 = ((haloTW64 + 3 + 3) / 4) * 4;
  static const int smem_per_block = []() {
    int dev = 0;
    cudaGetDevice(&dev);
    int v = 0;
    cudaDeviceGetAttribute(&v, cudaDevAttrMaxSharedMemoryPerBlock, dev);
    return v;
  }();
  const long double halo_smem_bytes =
      ((long double)KW * CinPerGroup * haloTD64 * haloTH64 * haloTWP64 +
