  const int smem_halo = halo_ok ? (int)halo_smem_bytes : 0;
  const int haloTD  = halo_ok ? (int)haloTD64  : 1;
  const int haloTH  = halo_ok ? (int)haloTH64  : 1;
  const int haloTW  = halo_ok ? (int)haloTW64  : 1;
