  const int64_t P = Dout * Hout * Wout;
  const int64_t spatial_tiles = (P + BM - 1) / BM;
  const int64_t oc_tiles_per_group = (CoutPerGroup + BN - 1) / BN;
  const int64_t haloTilesD = (Dout + HALO_TD_OUT - 1) / HALO_TD_OUT;
  const int64_t haloTilesH = (Hout + HALO_TH_OUT - 1) / HALO_TH_OUT;
  const int64_t haloTilesW = (Wout + HALO_TW_OUT - 1) / HALO_TW_OUT;
  const int64_t halo_spatial_tiles = haloTilesD * haloTilesH * haloTilesW;
  const int64_t launch_spatial_tiles =
      halo_ok ? halo_spatial_tiles : spatial_tiles;
  TORCH_CHECK(launch_spatial_tiles <= INT32_MAX,
              "Too many spatial tiles");
  TORCH_CHECK(groups * oc_tiles_per_group <= INT32_MAX,
              "Too many output-channel tiles");
  dim3 block(Threads);
  dim3 grid(
      (unsigned)launch_spatial_tiles,
      (unsigned)(groups * oc_tiles_per_group),
      (unsigned)N
