  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  if (halo_ok) {
    conv3d_cute_halo_kernel<float, RK_FULL, RK_PIPE>
        <<<grid, block, smem_halo, stream>>>(
        x_c.data_ptr<float>(),
        w_c.data_ptr<float>(),
        bias_ptr,
        y.data_ptr<float>(),
        (int)Cin,
        (int)Cout,
        (int)D,
        (int)H,
        (int)Wd,
        (int)KD,
        (int)KH,
        (int)KW,
        (int)Dout,
        (int)Hout,
        (int)Wout,
        (int)stride,
        (int)padding,
        (int)dilation,
        (int)CinPerGroup,
        (int)CoutPerGroup,
        (int)haloTilesD,
        (int)haloTilesH,
        (int)haloTilesW,
        haloTD,
