        w_c.data_ptr<float>(),
        bias_ptr,
        y.data_ptr<float>(),
        (int)Cin,
        (int)Cout,
        (int)D,
        (int)H,
        (int)Wd,
        (int)KD,
        (int)KH,
        (int)KW,
        (int)Dout,
        (int)Hout,
        (int)Wout,
        (int)stride,
        (int)padding,
        (int)dilation,
        (int)CinPerGroup,
        (int)CoutPerGroup
