conv3d_cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cstdint>

#include <cute/tensor.hpp>

using namespace cute;

// ---------------------------------------------------------------------------
// cp.async helpers (4-byte copies). src-size = 0 zero-fills shared memory,
// which gives us bounds-checked staging with implicit zero-padding.
// ---------------------------------------------------------------------------
template <typename T>
__device__ __forceinline__ void my_cp_async_4B(T* smem_ptr, const T* gmem_ptr, bool pred)
{
#if defined(__CUDA_ARCH__) && (__CUDA_ARCH__ >= 800)
  static_assert(sizeof(T) == 4, "my_cp_async_4B expects 4-byte elements");
  const unsigned saddr =
      static_cast<unsigned>(__cvta_generic_to_shared(smem_ptr));
  const int src_size = pred ? 4 : 0;
  asm volatile("cp.async.ca.shared.global [%0], [%1], 4, %2;\n"
               :: "r"(saddr), "l"(gmem_ptr), "r"(src_size));
#else
  *smem_ptr = pred ? *gmem_ptr : T(0);
#endif
}

__device__ __forceinline__ void my_cp_async_commit()
{
#if defined(__CUDA_ARCH__) && (__CUDA_ARCH__ >= 800)
  asm volatile("cp.async.commit_group;\n" ::);
#endif
}

template <int N>
__device__ __forceinline__ void my_cp_async_wait()
{
#if defined(__CUDA_ARCH__) && (__CUDA_ARCH__ >= 800)
  asm volatile("cp.async.wait_group %0;\n" :: "n"(N));
#endif
}

template <typename T, int RK, int STAGES>
__global__ void __launch_bounds__(128, 2) conv3d_cute_kernel(
    const T* __restrict__ X,
    const T* __restrict__ W,
    const T* __restrict__ B,
    T* __restrict__ Y,
    int Cin,
    int Cout,
    int D,
    int H,
    int Wd,
    int KD,
    int KH,
    int KW,
    int Dout,
    int Hout,
    int Wout,
    int stride,
    int padding,
    int dilation,
    int CinPerGroup,
    int CoutPerGroup)
{
  constexpr int BM      = 128;
  constexpr int BN      = 64;
  constexpr int Threads = 128;
  constexpr int TM      = 8;
  constexpr int TN      = 8;
  constexpr int RowThreads = BM / TM;
  constexpr int ColThreads = BN / TN;

  static_assert(BM % TM == 0, "BM must be divisible by TM");
  static_assert(BN % TN == 0, "BN must be divisible by TN");
  static_assert(RowThreads * ColThreads == Threads, "Invalid thread tile");

  const int tid = threadIdx.x;
  const int n   = blockIdx.z;

  const int oc_tiles_per_group = (CoutPerGroup + BN - 1) / BN;
  const int group   = (int)blockIdx.y / oc_tiles_per_group;
  const int oc_tile = (int)blockIdx.y - group * oc_tiles_per_group;

  const int oc0 = group * CoutPerGroup + oc_tile * BN;
  const int ci0 = group * CinPerGroup;

  const int p0 = (int)blockIdx.x * BM;
  const int P  = Dout * Hout * Wout;

  const int64_t sXn = (int64_t)Cin * D * H * Wd;
  const int64_t sXc = (int64_t)D * H * Wd;
  const int64_t sXd = (int64_t)H * Wd;
  const int64_t sXh = (int64_t)Wd;

  const int64_t sYn = (int64_t)Cout * Dout * Hout * Wout;
  const int64_t sYc = (int64_t)Dout * Hout * Wout;
  const int64_t sYd = (int64_t)Hout * Wout;
  const int64_t sYh = (int64_t)Wout;

  const int64_t sWo = (int64_t)CinPerGroup * KD * KH * KW;

  Tensor mY = make_tensor(
      make_gmem_ptr(Y + (int64_t)n * sYn),
      make_shape(Cout, Dout, Hout, Wout),
      make_stride(sYc, sYd, sYh, Int<1>{})
  );

  const T* Xn = X + (int64_t)n * sXn;
  const T* Xg = Xn + (int64_t)ci0 * sXc;

  // Shared-memory tiles with a compile-time stage count: STAGES=2 gives the
  // classic double-buffered pipeline, while STAGES=1 (used when the whole
  // reduction dimension fits) keeps a single full-K tile resident so every
  // global element is staged exactly once. Both use dynamic shared memory.
  extern __shared__ __align__(16) unsigned char dyn_smem[];
  T* sX_raw = reinterpret_cast<T*>(dyn_smem);
  T* sW_raw = sX_raw + (size_t)STAGES * RK * BM;
  Tensor sX = make_tensor(
      make_smem_ptr(sX_raw),
      make_layout(
          make_shape(Int<RK>{}, Int<BM>{}, Int<STAGES>{}),
          make_stride(Int<BM>{}, Int<1>{}, Int<RK * BM>{})
      )
  );
  Tensor sW = make_tensor(
      make_smem_ptr(sW_raw),
      make_layout(
          make_shape(Int<RK>{}, Int<BN>{}, Int<STAGES>{}),
          make_stride(Int<BN>{}, Int<1>{}, Int<RK * BN>{})
      )
  );

  __shared__ int sOD[BM];
  __shared__ int sOH[BM];
  __shared__ int sOW[BM];
  __shared__ int sBD[BM];
  __shared__ int sBH[BM];
  __shared__ int sBW[BM];
  __shared__ int4 sK[RK];

  for (int i = tid; i < BM; i += Threads) {
    const int p = p0 + i;

    int od = 0;
    int oh = 0;
    int ow = 0;

    if (p < P) {
      const int HW = Hout * Wout;
      od = p / HW;
      const int rem = p - od * HW;
      oh = rem / Wout;
      ow = rem - oh * Wout;
    }

    sOD[i] = od;
    sOH[i] = oh;
    sOW[i] = ow;
    sBD[i] = od * stride - padding;
    sBH[i] = oh * stride - padding;
    sBW[i] = ow * stride - padding;
  }

  __syncthreads();

  Tensor acc = make_tensor<T>(make_shape(Int<TM>{}, Int<TN>{}));
  clear(acc);

  const int row0 = (tid % RowThreads) * TM;
  const int col0 = (tid / RowThreads) * TN;

  const int R = CinPerGroup * KD * KH * KW;
  const int numKTiles = (R + RK - 1) / RK;

  // Asynchronous staged loader for one K-tile into shared-memory buffer `buf`.
  auto load_tile = [&](int r0, int buf) {
    // Stage the per-r kernel-offset metadata (dilated kd/kh/kw and the
    // local input channel) in shared memory. The r -> (ci, kd, kh, kw)
    // decomposition is computed once per K-tile by RK threads instead of
    // being recomputed with expensive integer div/mod for every staged
    // element, which removes the integer-pipe bottleneck from the gather.
    if (tid < RK) {
      const int r = r0 + tid;
      int4 m = make_int4(0, 0, 0, 0);
      if (r < R) {
        const int kw = r % KW;
        int t = r / KW;
        const int kh = t % KH;
        t /= KH;
        const int kd = t % KD;
        const int ci = t / KD;
        m.x = kd * dilation;
        m.y = kh * dilation;
        m.z = kw * dilation;
        m.w = ci;
      }
      sK[tid] = m;
    }
    __syncthreads();
    // ---- Stage X tile: (RK, BM) ----
    for (int idx = tid; idx < RK * BM; idx += Threads) {
      const int rr = idx / BM;
      const int i  = idx - rr * BM;
      const int r  = r0 + rr;
      const T* gptr = X;
      bool pred = false;
      if (r < R && (p0 + i) < P) {
        const int4 m = sK[rr];
        const int id = sBD[i] + m.x;
        const int ih = sBH[i] + m.y;
        const int iw = sBW[i] + m.z;
        if (id >= 0 && id < D &&
            ih >= 0 && ih < H &&
            iw >= 0 && iw < Wd) {
          gptr = Xg + (int64_t)m.w * sXc
                    + (int64_t)id * sXd
                    + (int64_t)ih * sXh
                    + (int64_t)iw;
          pred = true;
        }
      }
      my_cp_async_4B(&sX(rr, i, buf), gptr, pred);
    }
    // ---- Stage W tile: (RK, BN) ----
    // The weight tensor [Cout, CinPerGroup, KD, KH, KW] is contiguous in
    // the reduction index r = ((ci * KD + kd) * KH + kh) * KW + kw, so the
    // in-group weight offset equals r exactly; no decomposition needed.
    for (int idx = tid; idx < RK * BN; idx += Threads) {
      const int j  = idx / RK;
      const int rr = idx - j * RK;
      const int r  = r0 + rr;
      const T* gptr = W;
      bool pred = false;
      const int local_oc = oc_tile * BN + j;
      if (r < R && local_oc < CoutPerGroup) {
        const int oc = group * CoutPerGroup + local_oc;
        gptr = W + (int64_t)oc * sWo + r;
        pred = true;
      }
      my_cp_async_4B(&sW(rr, j, buf), gptr, pred);
    }
  };

  // Prologue: issue loads for the first K-tile.
  load_tile(0, 0);
  my_cp_async_commit();
  // All threads must finish READING tile-0's sK metadata before
  // iteration 0's load_tile() overwrites the shared sK buffer (WAR race).
  // This does not affect the in-flight cp.async group: completion is
  // still governed by cp.async.wait_group in the main loop.
  __syncthreads();

  // Pipelined main loop: overlap next-tile loads with current-tile compute.
  for (int kt = 0; kt < numKTiles; ++kt) {
    const int r0  = kt * RK;
    const int cur = (STAGES == 1) ? 0 : (kt & 1);

    if constexpr (STAGES > 1) {
      if (kt + 1 < numKTiles) {
        load_tile((kt + 1) * RK, (kt + 1) & 1);
        my_cp_async_commit();
        my_cp_async_wait<1>();   // current tile ready, next may still be in flight
      } else {
        my_cp_async_wait<0>();   // drain remaining groups
      }
    } else {
      // Single-stage configuration: the trailing __syncthreads() of the
      // previous iteration guarantees compute finished before the next
      // tile overwrites the buffer (no overlap, correct for any R).
      if (kt > 0) {
        load_tile(r0, 0);
        my_cp_async_commit();
      }
      my_cp_async_wait<0>();
    }

    __syncthreads();

    static_assert(TM % 4 == 0, "TM must be a multiple of 4 for float4 loads");
    static_assert(TN % 4 == 0, "TN must be a multiple of 4 for float4 loads");
    // Vectorized 128-bit shared-memory loads feeding the 8x8 register-
    // blocked outer product: 4 LDS.128 per rr for 64 FMAs, doubling the
    // compute-to-shared-load ratio versus the previous 8x4 thread tile.
    #pragma unroll 8
    for (int rr = 0; rr < RK; ++rr) {
      if (r0 + rr < R) {
        T xr[TM];
        #pragma unroll
        for (int q = 0; q < TM / 4; ++q) {
          const float4 xv =
              *reinterpret_cast<const float4*>(&sX(rr, row0 + 4 * q, cur));
          xr[4 * q + 0] = xv.x;
          xr[4 * q + 1] = xv.y;
          xr[4 * q + 2] = xv.z;
          xr[4 * q + 3] = xv.w;
        }
        T wr[TN];
        #pragma unroll
        for (int q = 0; q < TN / 4; ++q) {
          const float4 wv =
              *reinterpret_cast<const float4*>(&sW(rr, col0 + 4 * q, cur));
          wr[4 * q + 0] = wv.x;
          wr[4 * q + 1] = wv.y;
          wr[4 * q + 2] = wv.z;
          wr[4 * q + 3] = wv.w;
        }
        #pragma unroll
        for (int tn = 0; tn < TN; ++tn) {
          #pragma unroll
          for (int tm = 0; tm < TM; ++tm) {
            acc(tm, tn) += xr[tm] * wr[tn];
          }
        }
      }
    }

    __syncthreads();
  }

  #pragma unroll
  for (int tm = 0; tm < TM; ++tm) {
    const int i = row0 + tm;
    const int p = p0 + i;

    if (p >= P) {
      continue;
    }

    const int od = sOD[i];
    const int oh = sOH[i];
    const int ow = sOW[i];

    #pragma unroll
    for (int tn = 0; tn < TN; ++tn) {
      const int local_oc = oc_tile * BN + col0 + tn;

      if (local_oc >= CoutPerGroup) {
        continue;
      }

      const int oc = oc0 + col0 + tn;
      T value = acc(tm, tn);

      if (B != nullptr) {
        value += B[oc];
      }

      mY(oc, od, oh, ow) = value;
    }
  }
}

torch::Tensor conv3d_cute_forward(
    torch::Tensor x,
    torch::Tensor w,
    c10::optional<torch::Tensor> bias,
    int64_t stride,
    int64_t padding,
    int64_t dilation,
