  const int ci0 = group * CinPerGroup;

  const int p0 = (int)blockIdx.x * BM;
  const int P  = Dout * Hout * Wout;

  const int64_t sXn = (int64_t)Cin * D * H * Wd;
  const int64_t sXc = (int64_t)D * H * Wd;
  const int64_t sXd = (int64_t)H * Wd;
  const int64_t sXh = (int64_t)Wd;

  const int64_t sYn = (int64_t)Cout * Dout * Hout * Wout;
  const int64_t sYc = (int64_t)Dout * Hout * Wout;
  const int64_t sYd = (int64_t)Hout * Wout;
  const int64_t sYh = (int64_t)Wout;

  const int64_t sWo = (int64_t)CinPerGroup * KD * KH * KW;
  const int64_t sWc = (int64_t)KD * KH * KW;
  const int64_t sWd = (int64_t)KH * KW;
  const int64_t sWh = (int64_t)KW;

  Tensor mX = make_tensor(
      make_gmem_ptr(X + (int64_t)n * sXn),
      make_shape(Cin, D, H, Wd),
      make_stride(sXc, sXd, sXh, Int<1>{})
  );

  Tensor mW = make_tensor(
      make_gmem_ptr(W),
      make_shape(Cout, CinPerGroup, KD, KH, KW),
      make_stride(sWo, sWc, sWd, sWh, Int<1>{})
  );

  Tensor mY = make_tensor(
      make_gmem_ptr(Y + (int64_t)n * sYn),
      make_shape(Cout, Dout, Hout, Wout),
      make_stride(sYc, sYd, sYh, Int<1>{})
  );

  __shared__ T sX_raw[RK * BM];
  __shared__ T sW_raw[RK * BN];

  Tensor sX = make_tensor(
      make_smem_ptr(sX_raw),
      make_layout(
          make_shape(Int<RK>{}, Int<BM>{}),
          make_stride(Int<BM>{}, Int<1>{})
      )
  );

  Tensor sW = make_tensor(
      make_smem_ptr(sW_raw),
      make_layout(
          make_shape(Int<RK>{}, Int<BN>{}),
          make_stride(Int<BN>{}, Int<1>{})
      )
  );

  __shared__ int sOD[BM];
  __shared__ int sOH[BM];
  __shared__ int sOW[BM];
  __shared__ int sBD[BM];
  __shared__ int sBH[BM];
  __shared__ int sBW[BM];

  __shared__ int sCI[RK];
  __shared__ int sKD[RK];
  __shared__ int sKH[RK];
  __shared__ int sKW[RK];

  for (int i = tid; i < BM; i += Threads) {
    const int p = p0 + i;

    int od = 0;
    int oh = 0;
    int ow = 0;

    if (p < P) {
      const int HW = Hout * Wout;
      od = p / HW;
      const int rem = p - od * HW;
      oh = rem / Wout;
      ow = rem - oh * Wout;
    }

    sOD[i] = od;
    sOH[i] = oh;
    sOW[i] = ow;
    sBD[i] = od * stride - padding;
    sBH[i] = oh * stride - padding;
    sBW[i] = ow * stride - padding;
  }

  __syncthreads();

  Tensor acc = make_tensor<T>(make_shape(Int<TM>{}, Int<TN>{}));
  clear(acc);

  const int row0 = (tid % RowThreads) * TM;
  const int col0 = (tid / RowThreads) * TN;

  const int R = CinPerGroup * KD * KH * KW;

  for (int r0 = 0; r0 < R; r0 += RK) {
    if (tid < RK) {
      const int r = r0 + tid;

      int ci = 0;
      int kd = 0;
      int kh = 0;
      int kw = 0;

      if (r < R) {
        kw = r % KW;
        int t = r / KW;
        kh = t % KH;
        t /= KH;
        kd = t % KD;
        ci = t / KD;
      }

      sCI[tid] = ci;
      sKD[tid] = kd;
      sKH[tid] = kh;
      sKW[tid] = kw;
    }

    __syncthreads();

    for (int idx = tid; idx < RK * BM; idx += Threads) {
      const int rr = idx / BM;
      const int i  = idx - rr * BM;
      const int r  = r0 + rr;

      T value = T(0);

      if (r < R && (p0 + i) < P) {
        const int id = sBD[i] + sKD[rr] * dilation;
        const int ih = sBH[i] + sKH[rr] * dilation;
        const int iw = sBW[i] + sKW[rr] * dilation;

        if (id >= 0 && id < D &&
            ih >= 0 && ih < H &&
            iw >= 0 && iw < Wd) {
          value = mX(ci0 + sCI[rr], id, ih, iw);
        }
      }

      sX(rr, i) = value;
    }

    for (int idx = tid; idx < RK * BN; idx += Threads) {
      const int rr = idx / BN;
      const int j  = idx - rr * BN;
      const int r  = r0 + rr;

      T value = T(0);

      const int local_oc = oc_tile * BN + j;
      if (r < R && local_oc < CoutPerGroup) {
        const int oc = group * CoutPerGroup + local_oc;
        value = mW(oc, sCI[rr], sKD[rr], sKH[rr], sKW[rr]);
      }

      sW(rr, j) = value;
    }

    __syncthreads();

    #pragma unroll
    for (int rr = 0; rr < RK; ++rr) {
      if (r0 + rr < R) {
        #pragma unroll
        for (int tn = 0; tn < TN; ++tn) {
          const T wv = sW(rr, col0 + tn);

          #pragma unroll
          for (int tm = 0; tm < TM; ++tm) {
            acc(tm, tn) += sX(rr, row0 + tm) * wv;
          }
        }
      }
    }

    __syncthreads();
  }

  #pragma unroll
  for (int tm = 0; tm < TM; ++tm) {
    const int i = row0 + tm;
    const int p = p0 + i;

    if (p >= P) {
      continue;
    }

    const int od = sOD[i];
    const int oh = sOH[i];
    const int ow = sOW[i];

    #pragma unroll
    for (int tn = 0; tn < TN; ++tn) {
      const int local_oc = oc_tile * BN + col0 + tn;

      if (local_oc >= CoutPerGroup) {
        continue;
      }

      const int oc = oc0 + col0 + tn;
      T value = acc(tm, tn);

      if (B != nullptr) {
        value += B[oc];
      }

      mY(oc, od, oh, ow) = value;
    }
  }
}

torch::Tensor conv3d_cute_forward(
    torch::Tensor x,
    torch::Tensor w,
    c10::optional<torch::Tensor> bias,
    int64_t stride,
    int64_t padding,
    int64_t dilation,
    int64_t groups)
{
  TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
  TORCH_CHECK(w.is_cuda(), "w must be a CUDA tensor");
  if (bias.has_value()) {
    TORCH_CHECK(bias.value().is_cuda(), "bias must be a CUDA tensor");
  }

  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
  TORCH_CHECK(w.scalar_type() == at::kFloat, "w must be float32");
  if (bias.has_value()) {
    TORCH_CHECK(bias.value().scalar_type() == at::kFloat, "bias must be float32");
  }

  TORCH_CHECK(x.dim() == 5, "x must have shape [N, C_in, D, H, W]");
  TORCH_CHECK(w.dim() == 5, "w must have shape [C_out, C_in/groups, KD, KH, KW]");

  const int64_t N    = x.size(0);
  const int64_t Cin  = x.size(1);
  const int64_t D    = x.size(2);
  const int64_t H    = x.size(3);
  const int64_t Wd   = x.size(4);

  const int64_t Cout = w.size(0);
  const int64_t KD   = w.size(2);
  const int64_t KH   = w.size(3);
  const int64_t KW   = w.size(4);

  TORCH_CHECK(stride > 0, "stride must be positive");
  TORCH_CHECK(padding >= 0, "padding must be non-negative");
  TORCH_CHECK(dilation > 0, "dilation must be positive");
  TORCH_CHECK(groups > 0, "groups must be positive");

  TORCH_CHECK(Cin % groups == 0, "C_in must be divisible by groups");
  TORCH_CHECK(Cout % groups == 0, "C_out must be divisible by groups");

  const int64_t CinPerGroup  = Cin / groups;
  const int64_t CoutPerGroup = Cout / groups;

  TORCH_CHECK(w.size(1) == CinPerGroup,
              "w.size(1) must equal C_in / groups");

  if (bias.has_value()) {
    TORCH_CHECK(bias.value().dim() == 1 && bias.value().size(0) == Cout,
                "bias must have shape [C_out]");
  }

  const int64_t Dout =
      (D + 2 * padding - dilation * (KD - 1) - 1) / stride + 1;
  const int64_t Hout =
      (H + 2 * padding - dilation * (KH - 1) - 1) / stride + 1;
  const int64_t Wout =
      (Wd + 2 * padding - dilation * (KW - 1) - 1) / stride + 1;

  TORCH_CHECK(Dout > 0 && Hout > 0 && Wout > 0,
              "Computed output spatial dimensions must be positive");

  TORCH_CHECK(N <= 65535, "Batch size exceeds CUDA grid-z limit");
  TORCH_CHECK(Cin <= INT32_MAX && Cout <= INT32_MAX &&
              D <= INT32_MAX && H <= INT32_MAX && Wd <= INT32_MAX &&
              Dout <= INT32_MAX && Hout <= INT32_MAX && Wout <= INT32_MAX,
              "Tensor dimensions exceed 32-bit kernel indexing");

  auto x_c = x.contiguous();
  auto w_c = w.contiguous();

  torch::Tensor bias_c;
  const float* bias_ptr = nullptr;
  if (bias.has_value()) {
    bias_c = bias.value().contiguous();
    bias_ptr = bias_c.data_ptr<float>();
  }

  auto y = torch::empty({N, Cout, Dout, Hout, Wout}, x.options());

  constexpr int BM      = 128;
  constexpr int BN      = 64;
  constexpr int Threads = 256;

  const int64_t P = Dout * Hout * Wout;
  const int64_t spatial_tiles = (P + BM - 1) / BM;
  const int64_t oc_tiles_per_group = (CoutPerGroup + BN - 1) / BN;

  TORCH_CHECK(spatial_tiles <= INT32_MAX,
              "Too many spatial tiles");
  TORCH_CHECK(groups * oc_tiles_per_group <= INT32_MAX,
              "Too many output-channel tiles");

  dim3 block(Threads);
  dim3 grid(
      (unsigned)spatial_tiles,
      (unsigned)(groups * oc_tiles_per_group),
      (unsigned)N
  );

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

  conv3d_cute_kernel<float><<<grid, block, 0, stream>>>(
      x_c.data_ptr<float>(),
      w_c.data_ptr<float>(),
      bias_ptr,
      y.data_ptr<float>(),
      (int)Cin,
      (int)Cout,
      (int)D,
      (int)H,
      (int)Wd,
      (int)KD,
      (int)KH,
      (int)KW,
      (int)Dout,
      (int)Hout,
      (int)Wout,
      (int)stride,
      (int)padding,
      (int)dilation,
      (int)CinPerGroup,
      (int)CoutPerGroup
  );

  const cudaError_t err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess,
              "conv3d_cute_kernel launch failed: ",
              cudaGetErrorString(err));

  return y;
}
